// ==UserScript==
// @name         4chan X Nextel Reply Notifier
// @namespace    local.codex.4chanx.nextel-reply-notifier
// @version      1.1.0-alpha
// @description  Plays a cleaned classic Nextel chirp when 4chan X marks a new post as quoting you.
// @author       gorpix
// @homepageURL  https://github.com/gorpix/Nextel-for-4chan-X
// @supportURL   https://github.com/gorpix/Nextel-for-4chan-X/issues
// @updateURL    https://raw.githubusercontent.com/gorpix/Nextel-for-4chan-X/main/nextel-for-4chan-x.user.js
// @downloadURL  https://raw.githubusercontent.com/gorpix/Nextel-for-4chan-X/main/nextel-for-4chan-x.user.js
// @match        http://boards.4chan.org/*
// @match        https://boards.4chan.org/*
// @match        http://boards.4channel.org/*
// @match        https://boards.4channel.org/*
// @run-at       document-start
// @grant        none
// ==/UserScript==

(function () {
  'use strict';

  const chirp = new Audio('data:audio/wav;base64,');
  chirp.preload = 'auto';

  const baselinePosts = new Set();
  const eligiblePosts = new Set();
  const completedPosts = new Set();
  const expiryTimers = new Map();
  let armed = false;
  let notificationTimer = 0;

  function postID(post) {
    return post.id || post.querySelector('.post')?.id || '';
  }

  function playChirp() {
    chirp.currentTime = 0;
    const playback = chirp.play();
    if (playback && typeof playback.catch === 'function') {
      playback.catch(function () {});
    }
  }

  function queueNotification() {
    clearTimeout(notificationTimer);
    notificationTimer = setTimeout(playChirp, 120);
  }

  // Mirror 4chan X's own beep rules: only real thread posts (not hover previews
  // or inlined clones, whose IDs get a prefix), not hidden/filtered, not yours.
  function isRealThreadPost(post) {
    return /^pc\d+$/.test(post.id) && !post.closest('#qp, .inline, .dialog');
  }

  function isHidden(post) {
    return post.hidden ||
      post.classList.contains('post-hidden') ||
      !!post.querySelector(':scope > .stub');
  }

  function evaluatePost(post) {
    if (!(post instanceof Element) || !post.matches('.postContainer')) return;

    const id = postID(post);
    if (
      !id ||
      !eligiblePosts.has(id) ||
      completedPosts.has(id) ||
      !post.classList.contains('quotesYou') ||
      post.classList.contains('yourPost') ||
      !isRealThreadPost(post) ||
      isHidden(post)
    ) return;

    completedPosts.add(id);
    eligiblePosts.delete(id);
    clearTimeout(expiryTimers.get(id));
    expiryTimers.delete(id);

    if (document.hidden || !document.hasFocus()) queueNotification();
  }

  function registerPost(post) {
    if (!armed || !(post instanceof Element) || !post.matches('.postContainer')) return;

    const id = postID(post);
    if (!id || baselinePosts.has(id) || completedPosts.has(id) || eligiblePosts.has(id)) return;

    eligiblePosts.add(id);
    expiryTimers.set(id, setTimeout(function () {
      eligiblePosts.delete(id);
      completedPosts.add(id);
      expiryTimers.delete(id);
    }, 5000));

    setTimeout(function () { evaluatePost(post); }, 100);
  }

  function scanAddedNode(node) {
    if (!(node instanceof Element)) return;
    if (node.matches('.postContainer')) registerPost(node);
    node.querySelectorAll('.postContainer').forEach(registerPost);
  }

  function addTestShortcut() {
    const shortcuts = document.querySelector('#shortcuts');
    if (!shortcuts || document.querySelector('#shortcut-nextel-reply-test')) return;

    const wrapper = document.createElement('span');
    wrapper.id = 'shortcut-nextel-reply-test';
    wrapper.className = 'shortcut brackets-wrap';
    wrapper.dataset.index = '105';

    const button = document.createElement('a');
    button.href = 'javascript:;';
    button.title = 'Test Nextel reply chirp';
    button.textContent = 'Chirp';
    button.addEventListener('click', function (event) {
      event.preventDefault();
      playChirp();
    });

    wrapper.appendChild(button);
    const following = Array.from(shortcuts.querySelectorAll('[data-index]'))
      .find(function (item) { return Number(item.dataset.index) > 105; });
    shortcuts.insertBefore(wrapper, following || null);
  }

  function arm() {
    document.querySelectorAll('.postContainer').forEach(function (post) {
      const id = postID(post);
      if (id) baselinePosts.add(id);
    });
    addTestShortcut();
    armed = true;
  }

  function start() {
    if (!document.documentElement) {
      setTimeout(start, 0);
      return;
    }

    const observer = new MutationObserver(function (records) {
      for (const record of records) {
        if (record.type === 'childList') {
          record.addedNodes.forEach(scanAddedNode);
        } else if (record.type === 'attributes') {
          evaluatePost(record.target);
        }
      }
      addTestShortcut();
    });

    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['class'],
      childList: true,
      subtree: true
    });

    const armLater = function () { setTimeout(arm, 1200); };
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', armLater, {once: true});
    } else {
      armLater();
    }
  }

  start();
}());
